document.addEventListener('DOMContentLoaded',()=>{const header=document.querySelector('.header');const menu=document.querySelector('.menu-button');if(menu&&header){menu.addEventListener('click',()=>{const open=header.classList.toggle('menu-open');menu.setAttribute('aria-expanded',String(open))});header.querySelectorAll('.nav a').forEach(a=>a.addEventListener('click',()=>header.classList.remove('menu-open')))}document.querySelectorAll('[data-whatsapp-form]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(form);const message=`Здравствуйте! Меня зовут ${data.get('name')}. Интересует: ${data.get('service')}. Телефон: ${data.get('phone')}. Хочу узнать стоимость и договориться о замере.`;window.open(`https://wa.me/79385234437?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer')}))});
